// Per-exercise corrections from the owner's audit of the exercise library (exercise-library-audit sheet), keyed by lower-case exercise name.
// Anything set here beats the rules in flags.ts. Generated by scripts/import-exercise-audit.cjs; empty until the audit is done.

import type { ExerciseFlags } from "./types";

export type FlagOverride = Partial<Pick<ExerciseFlags, "level" | "hardness" | "grip" | "impact" | "spineLoaded" | "avoidFor" | "pregnancy" | "staple">>;

export const FLAG_OVERRIDES: Record<string, FlagOverride> = {};
